const void* ps5_gl_lookup(const char* name) {
  size_t lo = 0, hi = sizeof kTable / sizeof kTable[0];
  while (lo < hi) {
    size_t mid = (lo + hi) / 2;
    int c = strcmp(name, kTable[mid].name);
    if (c == 0) return kTable[mid].addr;
    if (c < 0) hi = mid; else lo = mid + 1;
  }
  return NULL;
}
